package com.example.campsitelottery

import android.media.ExifInterface
import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * Code and documentation generated by Claude (Anthropic, Claude Opus 5.5). Estimated AI-generated share of this file: ~100%
 * Tests the profile picture sizing rules in [ProfileImagePolicy] and saving pictures through [InMemoryUserRepository].
 */
class ProfileImageTest {

    @Test
    fun sampleSizeKeepsTheShorterSideAtLeastTheTarget() {
        assertEquals(1, ProfileImagePolicy.sampleSizeFor(300, 400, target = 256))
        assertEquals(2, ProfileImagePolicy.sampleSizeFor(600, 800, target = 256))
        assertEquals(8, ProfileImagePolicy.sampleSizeFor(4000, 3000, target = 256))
        // 3000 / 16 = 187 would drop below the target, so it stops at 8.
        assertTrue(3000 / ProfileImagePolicy.sampleSizeFor(4000, 3000, target = 256) >= 256)
    }

    @Test
    fun sampleSizeIsOneForSmallOrInvalidImages() {
        assertEquals(1, ProfileImagePolicy.sampleSizeFor(100, 100))
        assertEquals(1, ProfileImagePolicy.sampleSizeFor(0, 500))
        assertEquals(1, ProfileImagePolicy.sampleSizeFor(-1, -1))
    }

    @Test
    fun centerSquareCropsTheMiddleOfTheLongerSide() {
        assertEquals(Triple(100, 0, 200), ProfileImagePolicy.centerSquare(400, 200))
        assertEquals(Triple(0, 150, 300), ProfileImagePolicy.centerSquare(300, 600))
        assertEquals(Triple(0, 0, 50), ProfileImagePolicy.centerSquare(50, 50))
    }

    @Test
    fun everyExifOrientationHasATransform() {
        assertEquals(0f to false, ProfileImagePolicy.transformFor(ExifInterface.ORIENTATION_NORMAL))
        assertEquals(0f to false, ProfileImagePolicy.transformFor(ExifInterface.ORIENTATION_UNDEFINED))
        assertEquals(0f to true, ProfileImagePolicy.transformFor(ExifInterface.ORIENTATION_FLIP_HORIZONTAL))
        assertEquals(180f to false, ProfileImagePolicy.transformFor(ExifInterface.ORIENTATION_ROTATE_180))
        assertEquals(180f to true, ProfileImagePolicy.transformFor(ExifInterface.ORIENTATION_FLIP_VERTICAL))
        assertEquals(90f to true, ProfileImagePolicy.transformFor(ExifInterface.ORIENTATION_TRANSPOSE))
        assertEquals(90f to false, ProfileImagePolicy.transformFor(ExifInterface.ORIENTATION_ROTATE_90))
        assertEquals(270f to true, ProfileImagePolicy.transformFor(ExifInterface.ORIENTATION_TRANSVERSE))
        assertEquals(270f to false, ProfileImagePolicy.transformFor(ExifInterface.ORIENTATION_ROTATE_270))
    }

    @Test
    fun veryLongImagesAreDownsampledToBoundMemory() {
        // A 60000 x 500 panorama would be 30 MP at full size.
        val sample = ProfileImagePolicy.sampleSizeFor(60_000, 500)
        assertTrue((60_000L / sample) * (500L / sample) <= ProfileImagePolicy.MAX_DECODE_PIXELS)
        // Ordinary photos are unaffected by the cap.
        assertEquals(8, ProfileImagePolicy.sampleSizeFor(4000, 3000))
    }

    @Test
    fun displayDecodingFitsTheLongestSide() {
        assertEquals(1, ProfileImagePolicy.sampleSizeToFit(256, 256))
        assertEquals(1, ProfileImagePolicy.sampleSizeToFit(512, 300))
        assertEquals(2, ProfileImagePolicy.sampleSizeToFit(1000, 1000))
        assertEquals(32, ProfileImagePolicy.sampleSizeToFit(10_000, 100))
        // 1025 / 2 can decode to 513 pixels, so it needs 4.
        assertEquals(4, ProfileImagePolicy.sampleSizeToFit(1025, 100))
    }

    @Test
    fun thePixelCapAllowsForRoundingUp() {
        // At sample 2, 15999 x 1001 can decode to 8000 x 501 = 4,008,000 pixels.
        val sample = ProfileImagePolicy.sampleSizeFor(15_999, 1001)
        assertTrue(((15_999L + sample - 1) / sample) * ((1001L + sample - 1) / sample) <= ProfileImagePolicy.MAX_DECODE_PIXELS)
    }

    @Test
    fun base64PayloadDropsADataUrlPrefix() {
        assertEquals("QUJD", ProfileImagePolicy.base64Payload("data:image/jpeg;base64,QUJD"))
        assertEquals("QUJD", ProfileImagePolicy.base64Payload("QUJD"))
        assertEquals("QUJD", ProfileImagePolicy.base64Payload("  QUJD\n"))
    }

    private val repo = InMemoryUserRepository(listOf(User(userId = "u1", name = "Jane")))

    private fun setImage(userId: String, image: String?): Exception? {
        var error: Exception? = null
        var succeeded = false
        repo.setProfileImage(userId, image, onSuccess = { succeeded = true }, onFailure = { error = it })
        assertTrue("exactly one callback should run", succeeded != (error != null))
        return error
    }

    @Test
    fun addingChangingAndRemovingAPictureIsSaved() {
        assertNull(setImage("u1", "first"))
        assertEquals("first", repo.peek("u1")?.profileImageUrl)
        assertNull(setImage("u1", "second"))
        assertEquals("second", repo.peek("u1")?.profileImageUrl)
        assertNull(setImage("u1", null))
        assertNull(repo.peek("u1")?.profileImageUrl)
    }

    @Test
    fun settingAPictureLeavesTheRestOfTheProfileAlone() {
        setImage("u1", "pic")
        assertEquals("Jane", repo.peek("u1")?.name)
    }

    @Test
    fun aMissingProfileIsNotRecreated() {
        assertTrue(setImage("nobody", "pic") is NoSuchElementException)
        assertNull(repo.peek("nobody"))
    }

    @Test
    fun failuresAreReported() {
        repo.failWith = IllegalStateException("offline")
        assertEquals("offline", setImage("u1", "pic")?.message)
        repo.failWith = null
        assertNull(repo.peek("u1")?.profileImageUrl)
    }
}
